import type { VisualKey } from "@/lib/types";
import { cn } from "@/lib/utils";

/**
 * ---------------------------------------------------------------------------
 * ORIGINAL PRODUCT ARTWORK
 * ---------------------------------------------------------------------------
 * Every visual here is drawn from scratch as abstract vector geometry — cash
 * stacks, RP chevrons, progress bars, speedometers, vehicle silhouettes,
 * luxury patterns, map grids and metallic interface elements.
 *
 * No game screenshots, characters, logos or other third-party artwork are used
 * anywhere in this project. These are also resolution independent, so they
 * cost nothing to load and never cause layout shift.
 *
 * To use a real image instead, set `image: "/products/your-file.webp"` on the
 * product in `config/products.ts` — the card and product page will prefer it.
 */

type Accent = "violet" | "azure" | "gold" | "silver";

const accentByVisual: Record<VisualKey, Accent> = {
  "cash-stack": "gold",
  "cash-vault": "gold",
  "cash-skyline": "gold",
  "rank-chevrons": "violet",
  "stat-bars": "azure",
  "unlock-grid": "silver",
  "ultimate-core": "violet",
  "vehicle-silhouette": "azure",
  "account-shield": "silver",
  "custom-blueprint": "violet",
};

const accentHex: Record<Accent, { main: string; soft: string; deep: string }> = {
  violet: { main: "#ab97ee", soft: "#cbbdf6", deep: "#4a3888" },
  azure: { main: "#8fb2e6", soft: "#b9d0f2", deep: "#3d5c93" },
  gold: { main: "#dcc287", soft: "#f0dfae", deep: "#a4874b" },
  silver: { main: "#ccd2de", soft: "#e8ebf2", deep: "#5a6273" },
};

export function getVisualAccent(visual: VisualKey): Accent {
  return accentByVisual[visual];
}

function Frame({
  visual,
  children,
  label,
}: {
  visual: VisualKey;
  children: React.ReactNode;
  label: string;
}) {
  const accent = accentHex[accentByVisual[visual]];
  const uid = `pv-${visual}`;

  return (
    <svg
      viewBox="0 0 400 300"
      preserveAspectRatio="xMidYMid slice"
      className="h-full w-full"
      role="img"
      aria-label={label}
    >
      <defs>
        <linearGradient id={`${uid}-bg`} x1="0" y1="0" x2="400" y2="300" gradientUnits="userSpaceOnUse">
          <stop offset="0" stopColor="#0e0e18" />
          <stop offset="1" stopColor="#07070c" />
        </linearGradient>
        <radialGradient id={`${uid}-glow`} cx="0.5" cy="0.42" r="0.62">
          <stop offset="0" stopColor={accent.main} stopOpacity="0.34" />
          <stop offset="0.55" stopColor={accent.deep} stopOpacity="0.14" />
          <stop offset="1" stopColor="#000000" stopOpacity="0" />
        </radialGradient>
        <linearGradient id={`${uid}-metal`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#ffffff" stopOpacity="0.9" />
          <stop offset="1" stopColor={accent.main} stopOpacity="0.35" />
        </linearGradient>
        <linearGradient id={`${uid}-accent`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor={accent.soft} />
          <stop offset="1" stopColor={accent.deep} />
        </linearGradient>
        <pattern id={`${uid}-grid`} width="26" height="26" patternUnits="userSpaceOnUse">
          <path d="M26 0H0v26" fill="none" stroke="#ffffff" strokeOpacity="0.055" strokeWidth="1" />
        </pattern>
        <pattern id={`${uid}-lux`} width="34" height="34" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
          <path d="M0 17h34M17 0v34" stroke={accent.main} strokeOpacity="0.07" strokeWidth="1" />
          <circle cx="17" cy="17" r="2.4" fill={accent.main} fillOpacity="0.06" />
        </pattern>
      </defs>

      {/* base plate + map grid + luxury weave */}
      <rect width="400" height="300" fill={`url(#${uid}-bg)`} />
      <rect width="400" height="300" fill={`url(#${uid}-grid)`} />
      <rect width="400" height="300" fill={`url(#${uid}-lux)`} />
      <rect width="400" height="300" fill={`url(#${uid}-glow)`} />

      {children}

      {/* horizon sweep + vignette */}
      <path d="M0 236h400" stroke={accent.main} strokeOpacity="0.18" strokeWidth="1" />
      <rect
        width="400"
        height="300"
        fill="none"
        stroke="#ffffff"
        strokeOpacity="0.06"
        strokeWidth="1"
      />
    </svg>
  );
}

