const scenes: Record<VisualKey, (props: { uid: string }) => React.JSX.Element> = {
  "cash-stack": CashStack,
  "cash-vault": CashVault,
  "cash-skyline": CashSkyline,
  "rank-chevrons": RankChevrons,
  "stat-bars": StatBars,
  "unlock-grid": UnlockGrid,
  "ultimate-core": UltimateCore,
  "vehicle-silhouette": VehicleSilhouette,
  "account-shield": AccountShield,
  "custom-blueprint": CustomBlueprint,
};

export function ProductVisual({
  visual,
  label,
  className,
}: {
  visual: VisualKey;
  label: string;
  className?: string;
}) {
  const Scene = scenes[visual] ?? scenes["custom-blueprint"];
  return (
    <div className={cn("relative overflow-hidden bg-ink", className)}>
      <Frame visual={visual} label={label}>
        <Scene uid={`pv-${visual}`} />
      </Frame>
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 bg-[linear-gradient(to_top,rgba(5,5,9,0.82),rgba(5,5,9,0.05)_55%,transparent)]"
      />
    </div>
  );
}
