import type {
  BadgeId,
  CartItem,
  CurrencyCode,
  PlatformId,
  PriceTable,
} from "@/lib/types";
import { currencies, platforms } from "@/config/site";

/** Tiny classname joiner — avoids pulling in clsx/tailwind-merge. */
export function cn(...values: Array<string | false | null | undefined>): string {
  return values.filter(Boolean).join(" ");
}

export function getPlatformLabel(id: PlatformId): string {
  return platforms.find((platform) => platform.id === id)?.label ?? id;
}

export function getPlatformShortLabel(id: PlatformId): string {
  return platforms.find((platform) => platform.id === id)?.shortLabel ?? id;
}

export function getCurrency(code: CurrencyCode) {
  return currencies.find((currency) => currency.code === code) ?? currencies[0];
}

export const QUOTE_LABEL = "Request Quote";

/**
 * Formats a price for display. Returns "Request Quote" whenever a confirmed
 * price has not been published for that product / currency.
 */
export function formatPrice(
  price: PriceTable,
  currency: CurrencyCode,
  quoteRequired = true,
): string {
  if (quoteRequired || !price) return QUOTE_LABEL;
  const amount = price[currency];
  if (amount === undefined || amount === null) return QUOTE_LABEL;
  const meta = getCurrency(currency);
  try {
    return new Intl.NumberFormat(meta.locale, {
      style: "currency",
      currency,
      maximumFractionDigits: amount % 1 === 0 ? 0 : 2,
    }).format(amount);
  } catch {
    return `${meta.symbol}${amount}`;
  }
}

/** Numeric line value, or null when the line still needs a quote. */
export function getLineAmount(
  item: CartItem,
  currency: CurrencyCode,
): number | null {
  if (item.quoteRequired || !item.price) return null;
  const amount = item.price[currency];
  if (amount === undefined || amount === null) return null;
  return amount * item.quantity;
}

export interface CartTotals {
  /** Sum of the lines that have a confirmed price. */
  total: number;
  /** How many lines still need to be quoted. */
  quoteLines: number;
  /** True when nothing in the cart has a confirmed price. */
  allQuoted: boolean;
}

export function getCartTotals(
  items: CartItem[],
  currency: CurrencyCode,
): CartTotals {
  let total = 0;
  let quoteLines = 0;
  for (const item of items) {
    const amount = getLineAmount(item, currency);
    if (amount === null) quoteLines += 1;
    else total += amount;
  }
  return {
    total,
    quoteLines,
    allQuoted: items.length > 0 && quoteLines === items.length,
  };
}

export function formatCurrencyAmount(
  amount: number,
  currency: CurrencyCode,
): string {
  const meta = getCurrency(currency);
  try {
    return new Intl.NumberFormat(meta.locale, {
      style: "currency",
      currency,
      maximumFractionDigits: amount % 1 === 0 ? 0 : 2,
    }).format(amount);
  } catch {
    return `${meta.symbol}${amount}`;
  }
}

export const badgeLabels: Record<BadgeId, string> = {
  popular: "Popular",
  starter: "Starter",
  "best-value": "Best Value",
  premium: "Premium",
  bespoke: "Bespoke",
  new: "New",
};

/**
 * Order reference for a locally-stored order. This is a customer-facing
 * identifier for the support ticket — it is not proof of payment.
 */
export function createOrderReference(): string {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  const random =
    typeof crypto !== "undefined" && "getRandomValues" in crypto
      ? Array.from(crypto.getRandomValues(new Uint32Array(6)))
      : Array.from({ length: 6 }, () => Math.floor(Math.random() * 0xffffffff));
  for (const value of random) code += alphabet[value % alphabet.length];
  const stamp = new Date().toISOString().slice(2, 10).replace(/-/g, "");
  return `AE-${stamp}-${code}`;
}

export function formatDate(value: string): string {
  try {
    return new Date(value).toLocaleString(undefined, {
      dateStyle: "medium",
      timeStyle: "short",
    });
  } catch {
    return value;
  }
}

/** Stable key so identical configurations merge into one cart line. */
export function buildCartKey(
  productId: string,
  platform: PlatformId,
  optionSignature: string,
): string {
  return [productId, platform, optionSignature].filter(Boolean).join("::");
}

export function slugify(value: string): string {
  return value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}
