import type { Metadata } from "next";
import { LoadingScreen } from "@/components/layout/LoadingScreen";
import { Hero } from "@/components/home/Hero";
import { FeaturedCarousel } from "@/components/home/FeaturedCarousel";
import { PopularProducts } from "@/components/home/PopularProducts";
import { CategoryGrid } from "@/components/home/CategoryGrid";
import { CustomOrderPromo } from "@/components/home/CustomOrderPromo";
import { HowItWorks } from "@/components/home/HowItWorks";
import { VouchesPreview } from "@/components/home/VouchesPreview";
import { PaymentMethodsSection } from "@/components/home/PaymentMethodsSection";
import { FaqSection } from "@/components/home/FaqSection";
import { SupportCta } from "@/components/home/SupportCta";
import { GlowDivider } from "@/components/ui/Section";
import { siteConfig } from "@/config/site";
import { products } from "@/config/products";
import { categories } from "@/config/categories";

export const metadata: Metadata = {
  title: `${siteConfig.name} — Premium GTA Online Boosting Store`,
  description: siteConfig.shortDescription,
  alternates: { canonical: "/" },
};

export default function HomePage() {
  const storeJsonLd = {
    "@context": "https://schema.org",
    "@type": "Store",
    name: siteConfig.name,
    description: siteConfig.shortDescription,
    url: siteConfig.url,
    slogan: siteConfig.tagline,
    currenciesAccepted: "USD, INR",
    disambiguatingDescription: siteConfig.disclaimer,
    hasOfferCatalog: {
      "@type": "OfferCatalog",
      name: "GTA Online boosting packages",
      itemListElement: categories.map((category) => ({
        "@type": "OfferCatalog",
        name: category.title,
        description: category.description,
        itemListElement: products
          .filter((product) => product.category === category.id)
          .map((product) => ({
            "@type": "Offer",
            name: product.title,
            description: product.subtitle,
            url: `${siteConfig.url}/products/${product.slug}`,
            availability: "https://schema.org/InStock",
          })),
      })),
    },
  };

  const websiteJsonLd = {
    "@context": "https://schema.org",
    "@type": "WebSite",
    name: siteConfig.name,
    url: siteConfig.url,
    potentialAction: {
      "@type": "SearchAction",
      target: `${siteConfig.url}/shop?q={search_term_string}`,
      "query-input": "required name=search_term_string",
    },
  };

  return (
    <>
      <LoadingScreen />
      <Hero />
      <FeaturedCarousel />
      <PopularProducts />
      <GlowDivider />
      <CategoryGrid />
      <CustomOrderPromo />
      <HowItWorks />
      <GlowDivider />
      <VouchesPreview />
      <PaymentMethodsSection />
      <FaqSection limit={6} />
      <SupportCta />

      <script
        type="application/ld+json"
        // eslint-disable-next-line react/no-danger -- static, server-generated JSON-LD
        dangerouslySetInnerHTML={{ __html: JSON.stringify(storeJsonLd) }}
      />
      <script
        type="application/ld+json"
        // eslint-disable-next-line react/no-danger -- static, server-generated JSON-LD
        dangerouslySetInnerHTML={{ __html: JSON.stringify(websiteJsonLd) }}
      />
    </>
  );
}
