/**
 * Services and extras offered by the custom order builder (/custom-order).
 * Add or remove entries here to change what customers can request.
 */
export interface CustomService {
  id: string;
  label: string;
  description: string;
  visual: VisualKey;
  /** Labels for the "current" and "desired" value inputs. */
  currentLabel: string;
  desiredLabel: string;
  currentPlaceholder: string;
  desiredPlaceholder: string;
  /** Set false for services with no meaningful before/after value. */
  hasValues: boolean;
}

