import Link from "next/link";
import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "@/lib/utils";

type Variant = "primary" | "gold" | "outline" | "ghost" | "subtle" | "danger";
type Size = "sm" | "md" | "lg";

const base =
  "relative inline-flex items-center justify-center gap-2 rounded-lg font-medium tracking-tight " +
  "transition-[transform,box-shadow,background-color,border-color,color] duration-200 " +
  "ease-[cubic-bezier(.22,.61,.36,1)] select-none whitespace-nowrap " +
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-violet-300 " +
  "disabled:pointer-events-none disabled:opacity-45 active:translate-y-px";

const variants: Record<Variant, string> = {
  primary:
    "text-white border border-violet-400/40 bg-[linear-gradient(140deg,#7a62d0_0%,#5b47a8_55%,#453482_100%)] " +
    "shadow-[0_10px_40px_-16px_rgba(122,98,208,0.9)] hover:shadow-[0_14px_50px_-14px_rgba(143,120,224,0.95)] " +
    "hover:border-violet-300/60",
  gold:
    "text-[#1a1508] border border-gold-300/50 bg-[linear-gradient(140deg,#f0dfae_0%,#dcc287_45%,#b9975a_100%)] " +
    "shadow-[0_10px_40px_-18px_rgba(220,194,135,0.85)] hover:brightness-105",
  outline:
    "text-silver-100 border border-white/12 bg-white/[0.03] hover:bg-white/[0.07] hover:border-white/25",
  ghost:
    "text-silver-200 border border-transparent hover:bg-white/[0.06] hover:text-white",
  subtle:
    "text-silver-100 border border-white/10 bg-[#101018] hover:bg-[#16161f] hover:border-white/20",
  danger:
    "text-red-100 border border-red-500/30 bg-red-500/10 hover:bg-red-500/18 hover:border-red-400/50",
};

const sizes: Record<Size, string> = {
  sm: "h-9 px-3.5 text-[13px]",
  md: "h-11 px-5 text-sm",
  lg: "h-12 px-6 text-[15px] sm:h-[52px] sm:px-7",
};

interface CommonProps {
  variant?: Variant;
  size?: Size;
  fullWidth?: boolean;
  className?: string;
  children: ReactNode;
}

type ButtonProps = CommonProps &
  Omit<ComponentPropsWithoutRef<"button">, "className" | "children">;

type AnchorProps = CommonProps & {
  href: string;
  external?: boolean;
} & Omit<ComponentPropsWithoutRef<"a">, "className" | "children" | "href">;

function classes(
  variant: Variant = "primary",
  size: Size = "md",
  fullWidth?: boolean,
  className?: string,
) {
  return cn(base, variants[variant], sizes[size], fullWidth && "w-full", className);
}

export function Button({
  variant,
  size,
  fullWidth,
  className,
  children,
  type = "button",
  ...rest
}: ButtonProps) {
  return (
    <button
      type={type}
      className={classes(variant, size, fullWidth, className)}
      {...rest}
    >
      {children}
    </button>
  );
}

export function ButtonLink({
  variant,
  size,
  fullWidth,
  className,
  children,
  href,
  external,
  ...rest
}: AnchorProps) {
  const cls = classes(variant, size, fullWidth, className);

  if (external || href.startsWith("http") || href.startsWith("mailto:")) {
    return (
      <a
        href={href}
        className={cls}
        target={href.startsWith("mailto:") ? undefined : "_blank"}
        rel="noopener noreferrer"
        {...rest}
      >
        {children}
      </a>
    );
  }

  return (
    <Link href={href} className={cls} {...rest}>
      {children}
    </Link>
  );
}
