import { ArcCarousel } from "@/components/home/ArcCarousel";
import { Section, SectionHeading } from "@/components/ui/Section";
import { ButtonLink } from "@/components/ui/Button";
import { featuredProducts, products } from "@/config/products";
import { ArrowRight } from "lucide-react";

export function FeaturedCarousel() {
  // Fall back to the full catalogue if nothing is flagged as featured.
  const items = featuredProducts.length > 0 ? featuredProducts : products;

  return (
    <Section
      id="featured"
      ariaLabelledBy="featured-heading"
      className="overflow-hidden pt-6 sm:pt-10"
    >
      <div className="shell">
        <SectionHeading
          id="featured-heading"
          eyebrow="Featured packages"
          title="The Aether lineup"
          description="Browse the featured packages along the arc. Drag, swipe or use the arrows — the centred card is the one you are viewing."
          action={
            <ButtonLink href="/shop" variant="outline">
              Shop all
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </ButtonLink>
          }
        />
      </div>

      <div className="mt-10 sm:mt-12">
        <div className="shell max-w-[92rem]">
          <ArcCarousel products={items} />
        </div>
      </div>
    </Section>
  );
}
