import { ArrowRight } from "lucide-react";
import { ButtonLink } from "@/components/ui/Button";
import { Section, SectionHeading } from "@/components/ui/Section";
import { Reveal } from "@/components/ui/Reveal";
import { VouchCard } from "@/components/vouches/VouchCard";
import { hasRealVouches, vouches } from "@/config/vouches";

export function VouchesPreview() {
  const preview = vouches.slice(0, 3);

  return (
    <Section id="vouches" ariaLabelledBy="vouches-heading">
      <div className="shell">
        <SectionHeading
          id="vouches-heading"
          eyebrow="Feedback"
          title="Vouches"
          description={
            hasRealVouches
              ? "Feedback shared by customers, published with their permission."
              : "No customer reviews have been published yet. These slots are reserved for real vouches — nothing here was written on a customer's behalf."
          }
          action={
            <ButtonLink href="/vouches" variant="outline">
              View all vouches
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </ButtonLink>
          }
        />

        <ul className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {preview.map((vouch, index) => (
            <Reveal as="li" key={vouch.id} delay={index * 0.06} className="h-full">
              <VouchCard vouch={vouch} />
            </Reveal>
          ))}
        </ul>
      </div>
    </Section>
  );
}
