import { BadgeCheck, ImageOff, Quote } from "lucide-react";
import type { Vouch } from "@/lib/types";
import { getCategoryTitle } from "@/config/categories";
import { cn } from "@/lib/utils";

export function VouchCard({
  vouch,
  onOpenImage,
  className,
}: {
  vouch: Vouch;
  onOpenImage?: () => void;
  className?: string;
}) {
  const serviceLabel =
    vouch.service === "all" ? "All services" : getCategoryTitle(vouch.service);

  return (
    <figure
      className={cn(
        "flex h-full flex-col gap-4 rounded-2xl border p-5",
        vouch.placeholder
          ? "border-dashed border-white/12 bg-white/[0.015]"
          : "border-white/8 bg-white/[0.025]",
        className,
      )}
    >
      <div className="flex items-start justify-between gap-3">
        <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-1 text-[11px] uppercase tracking-[0.12em] text-silver-400">
          {serviceLabel}
        </span>
        {vouch.verifiedOrder && !vouch.placeholder ? (
          <span className="inline-flex items-center gap-1.5 rounded-md border border-violet-300/25 bg-violet-500/10 px-2 py-1 text-[11px] font-medium text-violet-200">
            <BadgeCheck className="h-3.5 w-3.5" aria-hidden="true" />
            Verified order
          </span>
        ) : null}
      </div>

      {vouch.placeholder ? (
        <div className="rounded-lg border border-dashed border-white/12 bg-black/20 px-3 py-2 text-[11px] font-medium uppercase tracking-[0.14em] text-silver-500">
          Placeholder — no real vouch published yet
        </div>
      ) : null}

      <blockquote className="relative flex-1">
        <Quote
          className="absolute -left-1 -top-1 h-5 w-5 text-white/8"
          aria-hidden="true"
        />
        <p
          className={cn(
            "relative pl-5 text-[13.5px] leading-relaxed",
            vouch.placeholder ? "text-silver-500 italic" : "text-silver-200",
          )}
        >
          {vouch.quote}
        </p>
      </blockquote>

      {vouch.screenshot ? (
        <button
          type="button"
          onClick={onOpenImage}
          className="group relative aspect-video w-full overflow-hidden rounded-lg border border-white/10"
        >
          {/* eslint-disable-next-line @next/next/no-img-element -- customer
              screenshots are dropped into /public and vary in size */}
          <img
            src={vouch.screenshot}
            alt={`Screenshot shared by ${vouch.author}`}
            loading="lazy"
            decoding="async"
            className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-[1.03]"
          />
          <span className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
          <span className="absolute bottom-2 left-2 rounded-md bg-black/60 px-2 py-1 text-[11px] text-silver-100">
            View screenshot
          </span>
        </button>
      ) : (
        <div className="flex aspect-video w-full flex-col items-center justify-center gap-2 rounded-lg border border-dashed border-white/10 bg-black/20 text-silver-600">
          <ImageOff className="h-5 w-5" aria-hidden="true" />
          <span className="text-[11.5px]">No screenshot added yet</span>
        </div>
      )}

      <figcaption className="flex items-center justify-between gap-3 border-t border-white/6 pt-3.5">
        <span
          className={cn(
            "text-[13px] font-medium",
            vouch.placeholder ? "text-silver-500" : "text-white",
          )}
        >
          {vouch.author}
        </span>
        {vouch.date ? (
          <span className="text-[12px] text-silver-500">{vouch.date}</span>
        ) : null}
      </figcaption>
    </figure>
  );
}
