import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import { ProductVisual } from "@/components/product/ProductVisual";
import { Section, SectionHeading } from "@/components/ui/Section";
import { Reveal } from "@/components/ui/Reveal";
import { categories } from "@/config/categories";
import { products } from "@/config/products";
import { cn } from "@/lib/utils";

export function CategoryGrid({
  heading = true,
  className,
}: {
  heading?: boolean;
  className?: string;
}) {
  const grid = (
    <ul
      className={cn(
        "grid gap-4 sm:grid-cols-2 lg:grid-cols-4",
        heading && "mt-10",
        className,
      )}
    >
      {categories.map((category, index) => {
        const count = products.filter(
          (product) => product.category === category.id,
        ).length;
        return (
          <Reveal as="li" key={category.id} delay={Math.min(index * 0.04, 0.24)}>
            <Link
              href={`/shop?category=${category.slug}`}
              className="group relative flex h-full flex-col overflow-hidden rounded-2xl border border-white/8 bg-[#0a0a11] transition-[border-color,transform,box-shadow] duration-300 hover:-translate-y-1 hover:border-white/20 hover:shadow-[0_28px_70px_-45px_rgba(122,98,208,0.8)]"
            >
              <div className="relative h-28 overflow-hidden">
                <ProductVisual
                  visual={category.visual}
                  label=""
                  className="h-full w-full transition-transform duration-700 group-hover:scale-105"
                />
              </div>
              <div className="flex flex-1 flex-col p-4">
                <div className="flex items-start justify-between gap-2">
                  <h3 className="text-[15.5px] font-semibold text-white">
                    {category.title}
                  </h3>
                  <ArrowUpRight
                    className="h-4 w-4 shrink-0 text-silver-500 transition-colors group-hover:text-violet-200"
                    aria-hidden="true"
                  />
                </div>
                <p className="mt-2 line-clamp-3 text-[12.5px] leading-relaxed text-silver-400">
                  {category.description}
                </p>
                <p className="mt-3 text-[11px] uppercase tracking-[0.16em] text-silver-500">
                  {count} {count === 1 ? "package" : "packages"}
                </p>
              </div>
            </Link>
          </Reveal>
        );
      })}
    </ul>
  );

  if (!heading) return grid;

  return (
    <Section id="categories" ariaLabelledBy="categories-heading">
      <div className="shell">
        <SectionHeading
          id="categories-heading"
          eyebrow="Browse the store"
          title="Shop by category"
          description="Eight categories covering everything from a first cash injection to a complete account overhaul."
        />
        {grid}
      </div>
    </Section>
  );
}
