import { ArrowRight, Lock, ShieldAlert } from "lucide-react";
import { ButtonLink } from "@/components/ui/Button";
import { Section, SectionHeading } from "@/components/ui/Section";
import { Reveal } from "@/components/ui/Reveal";
import { paymentMethods, paymentSteps } from "@/config/payments";
import { currencies } from "@/config/site";
import { cn } from "@/lib/utils";

export function PaymentMethodsSection({
  showSteps = true,
  className,
}: {
  showSteps?: boolean;
  className?: string;
}) {
  return (
    <Section id="payments" ariaLabelledBy="payments-heading" className={className}>
      <div className="shell">
        <SectionHeading
          id="payments-heading"
          eyebrow="Payments"
          title="Payment methods"
          description="Choose the currency and method that suits you. Payment details are shared only inside your private ticket, never on this website."
          action={
            <ButtonLink href="/payment-info" variant="outline">
              Payment information
              <ArrowRight className="h-4 w-4" aria-hidden="true" />
            </ButtonLink>
          }
        />

        <div className="mt-10 grid gap-4 lg:grid-cols-2">
          {currencies.map((currency, index) => (
            <Reveal key={currency.code} delay={index * 0.06}>
              <div className="h-full rounded-2xl border border-white/8 bg-white/[0.02] p-5 sm:p-6">
                <div className="flex items-center justify-between gap-3">
                  <h3 className="text-[15px] font-semibold text-white">
                    {currency.label}
                  </h3>
                  <span className="rounded-md border border-white/10 bg-white/[0.04] px-2.5 py-1 text-[12px] font-medium text-silver-300">
                    {currency.symbol} {currency.code}
                  </span>
                </div>
                <ul className="mt-4 grid gap-2 sm:grid-cols-2">
                  {paymentMethods
                    .filter((method) => method.currency === currency.code)
                    .map((method) => (
                      <li
                        key={method.id}
                        className="rounded-lg border border-white/8 bg-white/[0.025] px-3.5 py-3"
                      >
                        <p className="text-[13.5px] font-medium text-white">
                          {method.label}
                        </p>
                        <p className="mt-1 text-[12px] leading-snug text-silver-400">
                          {method.description}
                        </p>
                      </li>
                    ))}
                </ul>
              </div>
            </Reveal>
          ))}
        </div>

        {showSteps ? (
          <Reveal delay={0.08}>
            <ol className={cn("mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3")}>
              {paymentSteps.map((step, index) => (
                <li
                  key={step.title}
                  className="rounded-xl border border-white/8 bg-white/[0.02] p-4"
                >
                  <p className="font-display text-[12px] tracking-[0.18em] text-violet-200/70">
                    STEP {index + 1}
                  </p>
                  <p className="mt-2 text-[14px] font-medium text-white">
                    {step.title}
                  </p>
                  <p className="mt-1 text-[12.5px] leading-relaxed text-silver-400">
                    {step.detail}
                  </p>
                </li>
              ))}
            </ol>
          </Reveal>
        ) : null}

        <div className="mt-6 grid gap-3 sm:grid-cols-2">
          <p className="flex gap-2.5 rounded-xl border border-gold-300/15 bg-gold-400/[0.05] p-4 text-[12.5px] leading-relaxed text-gold-200/90">
            <Lock className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
            Payment handles are never published on this site. They are shared with
            you inside your private ticket after your order is confirmed.
          </p>
          <p className="flex gap-2.5 rounded-xl border border-white/10 bg-white/[0.02] p-4 text-[12.5px] leading-relaxed text-silver-300">
            <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
            Nothing is charged through this website. Pay only after an Aether staff
            member confirms your order and final price.
          </p>
        </div>
      </div>
    </Section>
  );
}
