export function getPaymentMethods(currency: CurrencyCode): PaymentMethod[] {
  return paymentMethods.filter((method) => method.currency === currency);
}

export function getPaymentMethod(id: string): PaymentMethod | undefined {
  return paymentMethods.find((method) => method.id === id);
}

